// PREVENTION GUARDRAIL - Brief Gate (runs BEFORE the agent drafts anything)
// From INC-2026-014 root causes: the Cedarwood brief was incomplete, had no Compliance sign-off,
// and carried claim language - and was processed anyway. This gate refuses such briefs.
const b = $input.first().json;
const reasons = [];
const front = [b.product_name, b.positioning].join(' ');

// a) claim language in the product name or positioning (wellness / medical / efficacy)
const claimRe = /\b(clinically|scientifically proven|medically|therapeutic|healing|cures?|treats|reduces? stress|relieves? stress|stress relief|improves? sleep|sleep (quality|aid)|aids? relaxation|boosts? mood|anti-?aging|calming|calm)\b/gi;
const claimHits = [...new Set((front.match(claimRe) || []).map(s => s.toLowerCase()))];
if (claimHits.length) reasons.push(`Claim language in name/positioning: ${claimHits.join(', ')}`);
if (/\bcalm\b/i.test(b.product_name || '')) reasons.push("Product name itself implies a wellness claim ('Calm') - rename at Stage 1");

// b) Compliance sign-off and substantiation
const claims = String(b.claims || '');
if (/not signed off|has not signed|no compliance sign-?off/i.test(claims)) reasons.push('No Compliance sign-off on the brief');
const weak = claims.match(/verbal confirmation|no document on file|supplier'?s? marketing materials|no chain-of-custody/gi);
if (weak) reasons.push(`Unsubstantiated claims: ${[...new Set(weak.map(s => s.toLowerCase()))].join('; ')}`);

// c) incomplete specs
const specGaps = ([b.materials, b.specs].join(' ').match(/not specified|to be confirmed|\bTBC\b|\(assumed\)|unspecified/gi) || []);
if (specGaps.length) reasons.push(`Incomplete specs: ${[...new Set(specGaps.map(s => s.toLowerCase()))].join(', ')}`);

const gate_passed = reasons.length === 0;
return [{ json: { ...b, gate_passed, gate_reasons: reasons } }];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = (arr, f = x => esc(typeof x === 'string' ? x : JSON.stringify(x))) => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + f(x) + '</li>').join('') + '</ul>' : '<p><i>None</i></p>';
const page = h => `<style>body{font-family:Arial,sans-serif;background:#F4F6FA;color:#1F2937;margin:0} .wrap{max-width:860px;margin:24px auto;background:#fff;border:1px solid #DBDFE7;border-radius:8px;padding:24px 28px} h2{color:#002060;margin-top:0} p{margin:8px 0} ul{margin:4px 0 8px 20px} h3{color:#002060;margin:14px 0 4px} table{border-collapse:collapse;width:100%;margin:6px 0 12px} td,th{border:1px solid #DBDFE7;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px} th{background:#002060;color:#fff} .tag{font-size:12px;color:#6B7280}</style><div class="wrap"><p class="tag">Kanvas Launch Studio · prototype</p>${h}</div>`;
const sgt = iso => { const d = new Date(new Date(iso).getTime() + 8*3600*1000); return d.toISOString().slice(0,16).replace('T',' ') + ' SGT'; };

const b = $input.first().json;
const html = `<h2>Brief refused at the gate</h2>
<p><b>${esc(b.product_name)}</b> (${esc(b.sku)}) was not drafted. Nothing was sent to the AI agent.</p>
<h3>Reasons</h3>${ul(b.gate_reasons)}
<p><b>Route:</b> back to Stage 1. Merchandising fixes the brief and obtains Compliance sign-off; Legal copied.</p>
<p><i>Audit log entry: Reviewer Action = Reject; Failure class = Brief refused at gate.</i></p>`;
return [{ json: { ...b, listing: null, requires_review: 'REFUSED AT BRIEF GATE - not drafted', html: page(html) } }];

