// STAGE 3 GUARDRAIL - Compliance Check (detection, not rewriting)
// Severity: AUTO-REJECT (07 prohibited phrases / 06 channel bans) > LEGAL REVIEW (implied wellness or efficacy)
//           > BRAND FIX (off-brand vocabulary, format breaches). Nothing is approved here; a human decides at Stage 4.

const brief = $('Parse Brief Fields').first().json;
const input = $input.first().json;

// 1. Read the agent output safely (the OpenAI node may return text or an already-parsed object)
let listing;
try {
  const raw = input.message?.content ?? input.choices?.[0]?.message?.content ?? input.response?.choices?.[0]?.message?.content ?? input.content ?? input.text;
  listing = (raw && typeof raw === 'object') ? raw : JSON.parse(raw);
} catch (e) {
  return [{ json: { sku: brief.sku, error: 'Could not parse agent output as JSON', raw: input, requires_review: 'BLOCKED - invalid agent output' } }];
}

const bullets = Array.isArray(listing.bullets) ? listing.bullets : [];
const allText = [listing.title || '', ...bullets, listing.description || ''].join(' \n ');
const lower = allText.toLowerCase();

// Whole-word / whole-phrase match, so 'green' does not fire on 'evergreen' and 'best' not on 'bestseller'
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = term => new RegExp('(^|[^a-z])' + esc(term.toLowerCase()) + '($|[^a-z])', 'i').test(lower);

// 2. AUTO-REJECT list: 07 Brand Voice 'Prohibited Phrases' + 06 channel prohibited claims + Priya Raman's seed list (13 Legal memo, v1.3)
const prohibited = {
  wellness: ['reduces stress', 'reduce stress', 'relieves stress', 'relieve stress', 'improve sleep', 'stress relief', 'improves sleep', 'better sleep', 'aids sleep', 'sleep aid', 'boosts mood', 'aids relaxation', 'calming effect', 'anxiety relief', 'reduces anxiety', 'reduce anxiety', 'lowers blood pressure', 'detoxifying', 'purifying', 'energising', 'energizing', 'balancing'],
  medical: ['clinically proven', 'clinically calming', 'scientifically proven', 'medically tested', 'therapeutic', 'healing', 'cures', 'treats', 'anti-aging', 'antimicrobial', 'fda approved'],
  sustainability: ['eco-friendly', 'eco friendly', 'green', '100% sustainable', 'organic', 'sustainable', 'zero waste', 'zero-waste'],
  natural_and_safety: ['100% natural', 'non-toxic', 'chemical-free', 'pet-safe', 'pet safe', 'safe for pets', 'child-safe', 'child safe', 'safe for children', 'hypoallergenic', 'non-allergenic'],
  superlative: ["world's finest", 'unmatched', 'unbeatable', 'number one', '#1', 'longest-lasting', 'longest lasting', 'strongest', 'best in class', 'best-in-class', 'superior to', "world's most"],
  time_pressure: ['limited time', 'only a few left', 'hurry', 'while stocks last'],
  warranty: ['lifetime warranty']
};
const prohibited_hits = [];
for (const [category, terms] of Object.entries(prohibited)) {
  for (const t of terms) if (has(t)) prohibited_hits.push({ term: t, category });
}
// 'best' is auto-reject, except instructions like 'for best results' / 'best before' (false positive in the Cedarwood test)
if (/\bbest\b(?!\s+(results|before))/i.test(allText)) prohibited_hits.push({ term: 'best', category: 'superlative' });
// 13 Legal memo + 16 test pack: prompt injection visible in the output (S-12) is blocked and escalated to the platform team
if (/\b(ignore (all |any )?(previous|prior|above) instructions|disregard (the )?(previous|above)|system prompt|you are now)\b/i.test(allText)) prohibited_hits.push({ term: 'prompt injection', category: 'injection' });
if (/only\s+\d+\s+left/i.test(allText)) prohibited_hits.push({ term: 'only X left', category: 'time_pressure' });

// 3. LEGAL REVIEW: implied wellness / efficacy claims that keyword lists miss
const impliedPatterns = [
  { label: 'calm / relax language', re: /\b(calm(ing|s)?|relax(ing|ation|es)?|unwind(ing)?|de-?stress(ing)?|soothing|tranquil)\b/i },
  { label: 'sleep language', re: /\b(sleep|restful|insomnia|drift off)\b/i },
  { label: 'mood or mind claim', re: /\b(mood|anxiety|wellbeing|well-being|mindful(ness)?|mental)\b/i },
  { label: 'body or health benefit', re: /\b(health(y|ier)?|immun\w*|detox\w*|purif(y|ies|ying)|breath(e|ing) easier|respiratory|aromatherapy|pain)\b/i },
  { label: 'efficacy wording', re: /\b(proven|tested|helps? (you )?(to )?(feel|reduce|improve|relieve|sleep)|designed to help|works to)\b/i },
  { label: 'certification claim', re: /\b(certified|approved by|recommended by|dermatolog\w*)\b/i },
  { label: 'sustainability claim', re: /\b(sustainab\w*|environment\w*|planet|carbon|eco-?\w*)\b/i }
];
const implied_claim_hits = impliedPatterns.filter(p => p.re.test(allText)).map(p => ({ pattern: p.label, match: allText.match(p.re)[0] }));

// 4. BRAND FIX: 07 'Don't use' vocabulary and empty intensifiers
const offBrand = ['premium', 'luxe', 'luxurious', 'elevate', 'elevates', 'stunning', 'complements', 'lifestyle', 'must-have', 'perfect', 'transform'];
const brand_voice_hits = offBrand.filter(has);
if (allText.includes('!')) brand_voice_hits.push('exclamation mark');

// 5. Amazon AE format rules (06)
const format_issues = [];
if (!listing.title) format_issues.push('Missing title');
else {
  if (listing.title.length > 200) format_issues.push(`Title is ${listing.title.length} chars (max 200)`);
  if (/\b(best|sale)\b/i.test(listing.title)) format_issues.push("Title contains promotional language ('Best' / 'Sale')");
}
if (bullets.length !== 5) format_issues.push(`Expected 5 bullets, got ${bullets.length}`);
bullets.forEach((b, i) => { if (String(b).length > 500) format_issues.push(`Bullet ${i + 1} is over 500 chars`); });
if (!listing.description) format_issues.push('Missing description');
else {
  if (listing.description.length > 2000) format_issues.push(`Description is ${listing.description.length} chars (max 2000)`);
  if (/<(?!br\s*\/?>)[a-z\/][^>]*>/i.test(listing.description)) format_issues.push('Description contains HTML other than <br>');
}
if (String(brief.target_market).toUpperCase() === 'AE') {
  const ar = listing.arabic_key_attributes || {};
  if (!ar.product_type || !ar.material) format_issues.push('UAE: Arabic key attributes missing');
}

// 6. Spec gaps in the brief itself (Stage 2 'Specs OK?' decision)
const spec_gaps = [];
const briefText = [brief.materials, brief.specs].join(' ');
[/not specified/i, /to be confirmed/i, /\bTBC\b/, /\(approx\)|approx\./i, /\(assumed\)/i, /unspecified/i, /not filled/i].forEach(re => {
  const m = briefText.match(re); if (m) spec_gaps.push(`Brief says '${m[0]}'`);
});
const missing_info = [...(Array.isArray(listing.missing_info) ? listing.missing_info : []), ...spec_gaps];

// 7. Route
let requires_review, route_to;
if (prohibited_hits.length) { requires_review = 'BLOCKED - AUTO-REJECT: prohibited language detected'; route_to = 'Stage 2 re-draft; Legal informed'; }
else if (implied_claim_hits.length) { requires_review = 'HOLD - LEGAL REVIEW: implied claim (wellness / efficacy / sustainability)'; route_to = 'Legal sign-off before Stage 4'; }
else if (missing_info.length) { requires_review = 'HOLD - SPEC GAP: brief incomplete'; route_to = 'Stage 1 Merchandising to correct brief'; }
else if (brand_voice_hits.length || format_issues.length) { requires_review = 'FIX - BRAND / FORMAT issues'; route_to = 'Stage 4 merchandiser edits'; }
else { requires_review = 'OK - ready for merchandiser review'; route_to = 'Stage 4 Merchandiser Review'; }

return [{
  json: {
    sku: brief.sku,
    product_name: brief.product_name,
    target_channel: brief.target_channel,
    listing,
    prohibited_hits,
    implied_claim_hits,
    brand_voice_hits,
    format_issues,
    missing_info,
    removed_claims: listing.removed_claims || [],
    requires_review,
    route_to,
    generated_at: new Date().toISOString()
  }
}];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = (arr, f = x => esc(typeof x === 'string' ? x : JSON.stringify(x))) => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + f(x) + '</li>').join('') + '</ul>' : '<p><i>None</i></p>';
const page = h => `<style>body{font-family:Arial,sans-serif;background:#F4F6FA;color:#1F2937;margin:0} .wrap{max-width:860px;margin:24px auto;background:#fff;border:1px solid #DBDFE7;border-radius:8px;padding:24px 28px} h2{color:#002060;margin-top:0} p{margin:8px 0} ul{margin:4px 0 8px 20px} h3{color:#002060;margin:14px 0 4px} table{border-collapse:collapse;width:100%;margin:6px 0 12px} td,th{border:1px solid #DBDFE7;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px} th{background:#002060;color:#fff} .tag{font-size:12px;color:#6B7280}</style><div class="wrap"><p class="tag">Kanvas Launch Studio · prototype</p>${h}</div>`;
const sgt = iso => { const d = new Date(new Date(iso).getTime() + 8*3600*1000); return d.toISOString().slice(0,16).replace('T',' ') + ' SGT'; };

const draftHtml = r => {
  const L = r.listing || {};
  const ar = L.arabic_key_attributes || {};
  return `<h3>Draft listing (${esc(r.target_channel)})</h3>
<p><b>Title:</b> ${esc(L.title)}</p>
<p><b>Bullets</b></p>${ul(L.bullets)}
<p><b>Description:</b> ${esc(L.description)}</p>
<p><b>Arabic key attributes:</b> ${esc(Object.values(ar).join(' | '))}</p>`;
};
const flagsHtml = r => `<h3>Compliance Check result</h3>
<p><b>${esc(r.requires_review)}</b> → ${esc(r.route_to)}</p>
<table><tr><th>Check</th><th>Result</th></tr>
<tr><td>Prohibited phrases (auto-block)</td><td>${esc((r.prohibited_hits||[]).map(h => h.term).join(', ') || 'none')}</td></tr>
<tr><td>Implied claims (Legal)</td><td>${esc((r.implied_claim_hits||[]).map(h => h.pattern + ': "' + h.match + '"').join('; ') || 'none')}</td></tr>
<tr><td>Brand voice</td><td>${esc((r.brand_voice_hits||[]).join(', ') || 'none')}</td></tr>
<tr><td>Format</td><td>${esc((r.format_issues||[]).join('; ') || 'none')}</td></tr>
<tr><td>Missing info</td><td>${esc((r.missing_info||[]).join('; ') || 'none')}</td></tr>
<tr><td>Claims removed by the agent</td><td>${esc((r.removed_claims||[]).map(c => c.claim || c).join('; ') || 'none')}</td></tr></table>`;

const r = $input.first().json;
const brief = $('Parse Brief Fields').first().json;
const s = String(r.requires_review || '');
const route_index = s.startsWith('BLOCKED') ? 0 : s.startsWith('HOLD - LEGAL') ? 1 : s.startsWith('HOLD - SPEC') ? 2 : 3;
const head = `<p><b>${esc(r.product_name)}</b> (${esc(r.sku)}) · brief from ${esc(brief.submitted_by)}</p>`;
let html = '';
if (route_index === 0) html = `<h2>Draft blocked automatically</h2>${head}<p>Prohibited language was found, so no person sees this draft. It goes back to Stage 2 for re-drafting and Legal is informed.</p>${flagsHtml(r)}`;
if (route_index === 2) html = `<h2>Back to Stage 1: brief incomplete</h2>${head}<p>The agent could not fill these gaps from the brief and did not guess.</p>${flagsHtml(r)}`;
return [{ json: { ...r, category: brief.category, submitted_by: brief.submitted_by, route_index,
  draft_html: draftHtml(r), flags_html: flagsHtml(r), html: html ? page(html) : '' } }];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = (arr, f = x => esc(typeof x === 'string' ? x : JSON.stringify(x))) => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + f(x) + '</li>').join('') + '</ul>' : '<p><i>None</i></p>';
const page = h => `<style>body{font-family:Arial,sans-serif;background:#F4F6FA;color:#1F2937;margin:0} .wrap{max-width:860px;margin:24px auto;background:#fff;border:1px solid #DBDFE7;border-radius:8px;padding:24px 28px} h2{color:#002060;margin-top:0} p{margin:8px 0} ul{margin:4px 0 8px 20px} h3{color:#002060;margin:14px 0 4px} table{border-collapse:collapse;width:100%;margin:6px 0 12px} td,th{border:1px solid #DBDFE7;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px} th{background:#002060;color:#fff} .tag{font-size:12px;color:#6B7280}</style><div class="wrap"><p class="tag">Kanvas Launch Studio · prototype</p>${h}</div>`;
const sgt = iso => { const d = new Date(new Date(iso).getTime() + 8*3600*1000); return d.toISOString().slice(0,16).replace('T',' ') + ' SGT'; };

const base = $('Route by Result').first().json; const l = $input.first().json;
const html = `<h2>Returned to Stage 2 by Legal</h2><p><b>${esc(base.product_name)}</b>: ${esc(l['Legal reviewer'])} struck the flagged wording.</p>
<p><b>Note:</b> ${esc(l['Legal note'] || '-')}</p><p>The agent re-drafts; the failure class is logged so repeats trigger a prompt review.</p>${base.flags_html}`;
return [{ json: { html: page(html) } }];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = (arr, f = x => esc(typeof x === 'string' ? x : JSON.stringify(x))) => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + f(x) + '</li>').join('') + '</ul>' : '<p><i>None</i></p>';
