const sgt = iso => { const d = new Date(new Date(iso).getTime() + 8*3600*1000); return d.toISOString().slice(0,16).replace('T',' ') + ' SGT'; };

const base = $('Route by Result').first().json;
const inp = $input.first().json;
const legal = inp['Legal decision'] ? { reviewer: inp['Legal reviewer'], decision: inp['Legal decision'], note: inp['Legal note'] || '', at: new Date().toISOString() } : null;
const legalHtml = legal ? `<p><b>Legal sign-off:</b> ${esc(legal.reviewer)}: ${esc(legal.decision)}${legal.note ? ' (' + esc(legal.note) + ')' : ''}</p>` : '<p><b>Legal:</b> no claim flag, so no Legal hold.</p>';
