const r = $('Stage 6 · Load CX History').first().json;
const input = $input.first().json;
let pack;
try { const raw = input.message?.content ?? input.content ?? input.text; pack = (raw && typeof raw === 'object') ? raw : JSON.parse(raw); }
catch (e) { pack = { faqs: [], macros: [], known_issues: [], do_not_claim: [], missing_info: ['CX pack could not be read'] }; }
const texts = [...(pack.faqs||[]).map(f => f.question + ' ' + f.answer), ...(pack.macros||[]).map(m => m.text), ...(pack.known_issues||[])].join(' \n ');
// Same detection logic as Stage 3, applied to customer-facing text. 'do_not_claim' is excluded: it is internal guidance.
const banned = ['clinically proven','scientifically proven','therapeutic','healing','cures','reduces stress','reduce stress','improves sleep','improve sleep','stress relief','eco-friendly','eco friendly','100% sustainable','sustainable','non-toxic','100% natural','organic','guaranteed','lifetime warranty','reduces anxiety','detoxifying','purifying','energising','zero waste','pet-safe','child-safe','hypoallergenic','non-allergenic','longest-lasting','strongest','best in class','superior to'];
const has = t => new RegExp('(^|[^a-z])' + t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '($|[^a-z])', 'i').test(texts);
const hits = banned.filter(has);
if (/\bbest\b(?!\s+(results|before))/i.test(texts)) hits.push('best');
const implied = [/\b(calm(ing)?|soothing|relax(ing|ation)?|unwind|sleep|mood|anxiety|wellbeing)\b/i, /\b(helps? (you )?(to )?(feel|reduce|improve|relieve|sleep)|designed to help)\b/i]
  .map(re => (texts.match(re) || [])[0]).filter(Boolean);
const status = hits.length ? 'BLOCKED - prohibited language in CX pack' : implied.length ? 'HOLD - Legal to check implied claims' : (pack.missing_info||[]).length ? 'READY WITH GAPS - confirm missing info' : 'READY for CX Lead sign-off';
const pack_html = `<p><b>${esc(r.product_name)}</b> · listing approved by ${esc(r.reviewer)} (${esc(r.decision)}) · ${esc(r.cx_history_note)}</p>
<h3>CX pack check: ${esc(status)}</h3>
<p>Prohibited: ${esc(hits.join(', ') || 'none')} · Implied claims: ${esc(implied.join(', ') || 'none')}</p>
<h3>FAQs</h3>${ul(pack.faqs, f => '<b>' + esc(f.question) + '</b><br>' + esc(f.answer))}
<h3>Macros</h3>${ul(pack.macros, m => '<b>' + esc(m.name) + '</b> (' + esc(m.use_when) + ')<br>' + esc(m.text))}
<h3>Known issues</h3>${ul(pack.known_issues)}
<h3>What we do not claim</h3>${ul(pack.do_not_claim)}
<h3>Missing info to confirm</h3>${ul(pack.missing_info)}`;
return [{ json: { ...r, cx_pack: pack, cx_status: status, cx_hits: hits, cx_implied: implied, pack_html } }];

